package ai.interviewiq.api.security;
import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Service; import java.nio.charset.StandardCharsets; import java.security.Key; import java.time.*; import java.util.*;
@Service public class JwtService { private final Key key; private final long expiry; public JwtService(@Value("${interviewiq.security.jwt-secret}") String secret,@Value("${interviewiq.security.jwt-expiry-seconds:900}") long expiry){if(secret.length()<32)throw new IllegalStateException("JWT secret must be at least 32 characters.");key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.expiry=expiry;} public String create(Long id,String email){Instant now=Instant.now();return Jwts.builder().subject(String.valueOf(id)).claim("email",email).issuedAt(Date.from(now)).expiration(Date.from(now.plusSeconds(expiry))).signWith(key).compact();} public Long userId(String token){return Long.valueOf(Jwts.parser().verifyWith((javax.crypto.SecretKey)key).build().parseSignedClaims(token).getPayload().getSubject());} public long expiry(){return expiry;} }
